import { hasPermissionCode } from '../utils/medicalPermissionCode';

const READ_CODE    = 'medical-incidents:monthly-incident-reports:read';
const WRITE_CODE   = 'medical-incidents:monthly-incident-reports:write';
const DELETE_CODE  = 'medical-incidents:monthly-incident-reports:delete';
const SUBMIT_CODE  = 'medical-incidents:monthly-incident-reports:submit';
const APPROVE_CODE = 'medical-incidents:monthly-incident-reports:approve';
const MANAGE_CODE  = 'medical-incidents:monthly-incident-reports:manage';

export { hasPermissionCode };

export interface MonthlyReportPermissions {
  canRead:      boolean;
  canWrite:     boolean;
  canCreate:    boolean;
  canUpdate:    boolean;
  canSave:      boolean;
  canSaveDraft: boolean;
  canSubmit:    boolean;
  canDelete:    boolean;
  canAi:        boolean;
  canPrint:     boolean;
  canExport:    boolean;
  canApprove:   boolean;
  canCancel:    boolean;
}

export function useMonthlyReportPermissions(): MonthlyReportPermissions {
  const canRead    = hasPermissionCode(READ_CODE);
  const canWrite   = hasPermissionCode(WRITE_CODE);
  const canDelete  = hasPermissionCode(DELETE_CODE);
  const canSubmit  = hasPermissionCode(SUBMIT_CODE);
  const canApprove = hasPermissionCode(APPROVE_CODE) || hasPermissionCode(MANAGE_CODE);
  const canCancel  = hasPermissionCode(MANAGE_CODE) || hasPermissionCode(SUBMIT_CODE);

  return {
    canRead,
    canWrite,
    canCreate:    canWrite,
    canUpdate:    canWrite,
    canSave:      canWrite,
    canSaveDraft: canWrite,
    canSubmit:    canSubmit,
    canDelete:    canDelete,
    canAi:        canWrite,
    canPrint:     canRead,
    canExport:    canRead,
    canApprove:   canApprove,
    canCancel:    canCancel,
  };
}
